  select coalesce(jsonb_agg(p.oid::regprocedure::text order by p.oid::regprocedure::text),'[]') into got from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.proname<>'rls_auto_enable' and has_function_privilege('authenticated',p.oid,'EXECUTE');
  if got<>(select jsonb_agg(x order by x) from jsonb_array_elements_text('["m1_check_editor()","m1_editor_articles()","m1_get_draft(uuid)","m1_operation_status(uuid,text)","m1_create_draft(uuid)","m1_save_draft(uuid,bigint,jsonb)","catalog_save_draft(uuid,bigint,jsonb,bigint)","m1_preview_draft(uuid,bigint,bigint,bigint)","m1_publish_draft(uuid,bigint,bigint,bigint,bigint,text)","m1_set_state(uuid,bigint,text,text)","catalog_editor_sectors()","catalog_editor_index(integer,integer)","catalog_editor_tree(bigint)","catalog_editor_sector(uuid,bigint,integer,integer)","catalog_editor_companies(integer,integer,text)","catalog_editor_company(uuid,bigint)","catalog_editor_group(uuid,bigint)","catalog_editor_membership(uuid,bigint)","catalog_editor_impact(uuid,bigint)","catalog_apply(bigint,text,text,uuid,jsonb)","catalog_operation_status(bigint,text,text,uuid,jsonb)"]'::jsonb) x) then raise exception 'CLOUD11_POST_AUTHENTICATED %',got;end if;
  -- anon keeps exactly the ten public read RPCs (company page since CLOUD12A).
  select coalesce(jsonb_agg(n.nspname||'.'||p.proname order by p.proname),'[]') into got from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname in ('public','private','judoju_control') and p.proname<>'rls_auto_enable' and has_function_privilege('anon',p.oid,'EXECUTE');
  if got<>'["public.catalog_public_articles","public.catalog_public_company","public.catalog_public_company_sectors","public.catalog_public_saved","public.catalog_public_search_companies","public.catalog_public_search_news","public.catalog_public_sector_page","public.catalog_public_tree","public.m1_public_article","public.m1_public_identity"]'::jsonb then raise exception 'CLOUD11_POST_ANON %',got;end if;
  -- service_role may execute exactly the three session RPCs and this stage's revoke/status/signout functions.
  select coalesce(jsonb_agg(n.nspname||'.'||p.proname order by n.nspname||'.'||p.proname),'[]') into got from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname in ('public','private','judoju_control') and p.proname<>'rls_auto_enable' and has_function_privilege('service_role',p.oid,'EXECUTE');
  if got<>'["public.admin_online_revoke","public.admin_online_signout","public.admin_online_status","public.m1_close_admin_session","public.m1_open_admin_session","public.m1_read_admin_session"]'::jsonb
    then raise exception 'CLOUD11_POST_SERVICE %',got;end if;
  if (select count(*) from private.admin_memberships where active)<>1 or (select raw_app_meta_data->>'app_role' from auth.users where id='e85049b7-7306-42ad-ac16-6c4bf5e82212')<>'admin' then raise exception 'CLOUD11_POST_OWNER';end if;
  if (select provolatile from pg_proc where oid='private.is_admin()'::regprocedure)<>'v' then raise exception 'CLOUD11_POST_IS_ADMIN';end if;
end$post$;
notify pgrst,'reload schema';
commit;
